/**
 * Names avoid `message` (Kotlin's `Throwable.message`) and `Protocol` (reserved in Swift).
 */
sealed class FfiSyncException: kotlin.Exception() {
    
    class WrongCode(
        
        val `attemptsLeft`: kotlin.UInt
        ) : FfiSyncException() {
        override val message
            get() = "attemptsLeft=${ `attemptsLeft` }"
    }
    
    class DifferentVault(
        ) : FfiSyncException() {
        override val message
            get() = ""
    }
    
    class NoVault(
        ) : FfiSyncException() {
        override val message
            get() = ""
    }
    
    class Version(
        ) : FfiSyncException() {
        override val message
            get() = ""
    }
    
    class Expired(
        ) : FfiSyncException() {
        override val message
            get() = ""
    }
    
    class Stopped(
        ) : FfiSyncException() {
        override val message
            get() = ""
    }
    
    class Io(
        
        val `detail`: kotlin.String
        ) : FfiSyncException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Store(
        
        val `detail`: kotlin.String
        ) : FfiSyncException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * Not `Protocol`: Swift can't have a type member with that name.
     */
    class Unexpected(
        ) : FfiSyncException() {
        override val message
            get() = ""
    }
    

